-- ============================================================
-- Migration 014 — Point seeded package image rows at local artwork
-- ============================================================
-- The 10 seeded packages (1..10) previously referenced remote
-- Unsplash URLs. This migration rewrites those references to the
-- locally generated artwork stored in the backend at:
--     backend/storage/uploads/packages/pkg{N}_{1..3}.jpg
--
-- The files are generated by  tools/generate_package_images.ps1
-- (run once from the repo root) and are committed with the repo,
-- so nothing external is required at runtime.
--
-- Idempotent: re-running produces the same result.
-- Safe: only touches rows for package_id 1..10; user-uploaded
-- images (e.g. the admin test package 11) are left untouched.
-- ============================================================

-- Primary / cover images -> pkg{N}_1.jpg
UPDATE package_image
SET image_url = CONCAT('/storage/uploads/packages/pkg', package_id, '_1.jpg')
WHERE package_id BETWEEN 1 AND 10
  AND (image_type = 'primary' OR display_order = 1);

-- First gallery image -> pkg{N}_2.jpg
UPDATE package_image
SET image_url = CONCAT('/storage/uploads/packages/pkg', package_id, '_2.jpg')
WHERE package_id BETWEEN 1 AND 10
  AND image_type = 'gallery'
  AND display_order = 2;

-- Remaining gallery images -> pkg{N}_3.jpg
UPDATE package_image
SET image_url = CONCAT('/storage/uploads/packages/pkg', package_id, '_3.jpg')
WHERE package_id BETWEEN 1 AND 10
  AND image_type = 'gallery'
  AND display_order > 2;

-- Keep gallery captions consistent with the artwork variants
UPDATE package_image
SET caption = CONCAT(package_image.caption, ' (TravelEase artwork)')
WHERE package_id BETWEEN 1 AND 10
  AND image_type = 'gallery'
  AND image_url LIKE '/storage/uploads/packages/pkg%'
  AND (caption IS NULL OR caption NOT LIKE '%(TravelEase artwork)');

-- Denormalized cover column on the package itself
UPDATE tour_package
SET cover_image_url = CONCAT('/storage/uploads/packages/pkg', package_id, '_1.jpg')
WHERE package_id BETWEEN 1 AND 10
  AND (cover_image_url IS NULL OR cover_image_url LIKE 'https://images.unsplash%');
